package com.fasterxml.jackson.databind.ser;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.io.SerializedString;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonObjectFormatVisitor;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.ser.impl.PropertySerializerMap;
import com.fasterxml.jackson.databind.ser.impl.UnwrappingBeanPropertyWriter;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.databind.util.NameTransformer;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BeanPropertyWriter_serializeAsField_TriageGen1Test {

    private BeanPropertyWriter writer;
    private JsonGenerator jgen;
    private SerializerProvider prov;
    private PropertySerializerMap serializerMap;
    private JsonSerializer<Object> serializer;
    private JsonSerializer<Object> nullSerializer;
    private JavaType javaType;

    // Marker for empty suppression test
    private static final Object MARKER_FOR_EMPTY = new Object();

    @Before
    public void setUp() throws Exception {
        jgen = mock(JsonGenerator.class);
        prov = mock(SerializerProvider.class);
        serializerMap = mock(PropertySerializerMap.class);
        serializer = mock(JsonSerializer.class);
        nullSerializer = mock(JsonSerializer.class);
        javaType = mock(JavaType.class);

        // We use a subclass or reflection because BeanPropertyWriter is complex to instantiate
        // For testing purposes, we mock the behavior of the dependencies via reflection 
        // or assume a controlled environment.
        writer = mock(BeanPropertyWriter.class, CALLS_REAL_METHODS);

        // Injecting private fields via reflection to simulate the internal state
        setInternalField(writer, "_name", new com.fasterxml.jackson.core.io.SerializedString("testField"));
        setInternalField(writer, "_dynamicSerializers", serializerMap);
        setInternalField(writer, "_serializer", null); // Force dynamic lookup
        setInternalField(writer, "_typeSerializer", null);
    }

    private void setInternalField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testSerializeAsField_ValueIsNull_WithNullSerializer() throws Exception {
        Object bean = new Object();
        when(writer.get(bean)).thenReturn(null);
        setInternalField(writer, "_nullSerializer", nullSerializer);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(nullSerializer).serialize(null, jgen, prov);
    }

    @Test
    public void testSerializeAsField_ValueIsNull_NoNullSerializer() throws Exception {
        Object bean = new Object();
        when(writer.get(bean)).thenReturn(null);
        setInternalField(writer, "_nullSerializer", null);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen, never()).writeFieldName(any());
    }

    @Test
    public void testSerializeAsField_FindDynamicSerializer() throws Exception {
        Object bean = new Object();
        Object value = "hello";
        when(writer.get(bean)).thenReturn(value);
        when(serializerMap.serializerFor(value.getClass())).thenReturn(serializer);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(serializer).serialize(value, jgen, prov);
    }

    @Test
    public void testSerializeAsField_FindAndAddDynamicSerializer() throws Exception {
        Object bean = new Object();
        Object value = 123;
        when(writer.get(bean)).thenReturn(value);
        when(serializerMap.serializerFor(Integer.class)).thenReturn(null);
        // Simulate _findAndAddDynamic returning a serializer
        doReturn(serializer).when(writer)._findAndAddDynamic(eq(serializerMap), eq(Integer.class), eq(prov));

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(serializer).serialize(value, jgen, prov);
    }

    @Test
    public void testSerializeAsField_SuppressEmptyValue() throws Exception {
        Object bean = new Object();
        Object value = new Object(); 
        when(writer.get(bean)).thenReturn(value);
        when(serializerMap.serializerFor(value.getClass())).thenReturn(serializer);
        setInternalField(writer, "_suppressableValue", MARKER_FOR_EMPTY);
        when(serializer.isEmpty(value)).thenReturn(true);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen, never()).writeFieldName(any());
    }

    @Test
    public void testSerializeAsField_SuppressSpecificValue() throws Exception {
        Object bean = new Object();
        Object value = "suppressMe";
        Object targetValue = "suppressMe";
        when(writer.get(bean)).thenReturn(value);
        when(serializerMap.serializerFor(value.getClass())).thenReturn(serializer);
        setInternalField(writer, "_suppressableValue", targetValue);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen, never()).writeFieldName(any());
    }

    @Test
    public void testSerializeAsField_HandleSelfReference() throws Exception {
        Object bean = new Object();
        when(writer.get(bean)).thenReturn(bean); // Value is same as bean
        when(serializerMap.serializerFor(bean.getClass())).thenReturn(serializer);

        writer.serializeAsField(bean, jgen, prov);

        verify(writer)._handleSelfReference(eq(bean), eq(serializer));
        verify(jgen).writeFieldName(any());
        verify(serializer).serialize(bean, jgen, prov);
    }

    @Test
    public void testSerializeAsField_WithTypeSerializer() throws Exception {
        Object bean = new Object();
        Object value = "data";
        JsonSerializer<Object> typeSer = mock(JsonSerializer.class);

        when(writer.get(bean)).thenReturn(value);
        when(serializerMap.serializerFor(value.getClass())).thenReturn(serializer);
        setInternalField(writer, "_typeSerializer", typeSer);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(serializer).serializeWithType(value, jgen, prov, typeSer);
        verify(serializer, never()).serialize(any(), any(), any());
    }

    @Test
    public void testSerializeAsField_WithExistingSerializer() throws Exception {
        Object bean = new Object();
        Object value = "data";
        setInternalField(writer, "_serializer", serializer);
        when(writer.get(bean)).thenReturn(value);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(serializer).serialize(value, jgen, prov);
        verify(serializerMap, never()).serializerFor(any());
    }
}
